                WHEN 'lon' THEN u.lon IS NOT DISTINCT FROM p.written::double precision
                WHEN 'geom' THEN u.geom IS NOT DISTINCT FROM p.written::geometry
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM p.written::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM p.written::character varying
                WHEN 'site_type' THEN u.site_type IS NOT DISTINCT FROM p.written::character varying
                WHEN 'source_url' THEN u.source_url IS NOT DISTINCT FROM p.written::text
                ELSE false END
